(function () {
  "use strict";

  const DATA = window.COURSE_DATA || { courses: [], terms: [] };
  const COURSES = DATA.courses;
  const TERMS = DATA.terms;

  const REGISTRATIONS_KEY = "campusflow.registrations.v1";
  const PROFILE_KEY = "campusflow.profile.v1";

  const DEFAULT_PROFILE = {
    name: "Jordan Rivera",
    email: "jordan.rivera@university.edu",
    studentId: "U20260418",
    program: "BSc Computer Science",
    year: "2nd year",
    pronouns: "they/them",
    interests: "Web development, artificial intelligence, accessible design",
    emailUpdates: true,
    waitlistAlerts: true
  };

  const SEED_REGISTRATIONS = [
    { courseId: "cs210", term: "Fall 2026", registeredAt: "2026-09-02T10:00:00.000Z" },
    { courseId: "art115", term: "Fall 2026", registeredAt: "2026-09-03T14:30:00.000Z" }
  ];

  const DEPARTMENT_THEMES = {
    "Computer Science": "violet",
    "Mathematics": "blue",
    "Biology": "green",
    "Psychology": "pink",
    "Art & Design": "orange",
    "Business": "amber",
    "Environmental Studies": "teal",
    "Music": "fuchsia",
    "English": "rose",
    "Physics": "indigo"
  };

  const DAY_ORDER = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
  const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  let registrations = null;
  let toastTimer = null;
  let modal = null;

  function safeStorageGet(key) {
    try {
      return window.localStorage.getItem(key);
    } catch (error) {
      return null;
    }
  }

  function safeStorageSet(key, value) {
    try {
      window.localStorage.setItem(key, value);
    } catch (error) {
      /* Storage may be unavailable; the app still works for this page. */
    }
  }

  function escapeHTML(value) {
    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function getCourse(courseId) {
    return COURSES.find(function (course) {
      return course.id === courseId;
    }) || null;
  }

  function getTheme(department) {
    return DEPARTMENT_THEMES[department] || "violet";
  }

  function getAvailableSeats(course) {
    return Math.max(0, course.seats - course.seatsTaken);
  }

  function isFull(course) {
    return getAvailableSeats(course) <= 0;
  }

  function formatSchedule(course) {
    if (!course.days || course.days.length === 0) {
      return "Self-paced";
    }
    return course.days.join(", ") + " · " + course.time;
  }

  function loadRegistrations() {
    if (registrations !== null) {
      return registrations.slice();
    }

    const stored = safeStorageGet(REGISTRATIONS_KEY);

    if (stored === null) {
      registrations = SEED_REGISTRATIONS.slice();
      safeStorageSet(REGISTRATIONS_KEY, JSON.stringify(registrations));
      return registrations.slice();
    }

    let parsed = [];
    try {
      parsed = JSON.parse(stored);
    } catch (error) {
      parsed = [];
    }

    if (!Array.isArray(parsed)) {
      parsed = [];
    }

    registrations = parsed.filter(function (entry) {
      return entry && typeof entry.courseId === "string" && getCourse(entry.courseId) && typeof entry.term === "string";
    });

    return registrations.slice();
  }

  function persistRegistrations() {
    safeStorageSet(REGISTRATIONS_KEY, JSON.stringify(registrations || []));
  }

  function getRegistrations() {
    return loadRegistrations();
  }

  function getRegistrationFor(courseId) {
    return getRegistrations().find(function (entry) {
      return entry.courseId === courseId;
    }) || null;
  }

  function isRegistered(courseId) {
    return Boolean(getRegistrationFor(courseId));
  }

  function addRegistration(courseId, term) {
    const course = getCourse(courseId);
    if (!course || isRegistered(courseId) || isFull(course)) {
      return false;
    }

    loadRegistrations();
    registrations.push({
      courseId: courseId,
      term: term,
      registeredAt: new Date().toISOString()
    });
    persistRegistrations();
    return true;
  }

  function removeRegistration(courseId) {
    loadRegistrations();
    const previousLength = registrations.length;
    registrations = registrations.filter(function (entry) {
      return entry.courseId !== courseId;
    });

    if (registrations.length !== previousLength) {
      persistRegistrations();
      return true;
    }
    return false;
  }

  function loadProfile() {
    const stored = safeStorageGet(PROFILE_KEY);
    if (!stored) {
      return Object.assign({}, DEFAULT_PROFILE);
    }

    try {
      const parsed = JSON.parse(stored);
      if (!parsed || typeof parsed !== "object") {
        return Object.assign({}, DEFAULT_PROFILE);
      }
      return Object.assign({}, DEFAULT_PROFILE, parsed);
    } catch (error) {
      return Object.assign({}, DEFAULT_PROFILE);
    }
  }

  function saveProfile(profile) {
    safeStorageSet(PROFILE_KEY, JSON.stringify(Object.assign({}, DEFAULT_PROFILE, profile)));
  }

  function getInitials(name) {
    return String(name || "")
      .trim()
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map(function (part) {
        return part.charAt(0).toUpperCase();
      })
      .join("") || "ST";
  }

  function createCourseCard(course, idPrefix) {
    const registered = isRegistered(course.id);
    const full = isFull(course);
    const available = getAvailableSeats(course);
    const titleId = idPrefix + "-" + course.id + "-title";
    const theme = getTheme(course.department);
    const seatText = full ? "Course full" : available + " seat" + (available === 1 ? "" : "s") + " left";
    const seatClass = full ? "seats seats--full" : "seats";

    let action;
    if (registered) {
      action = '<span class="status-pill status-pill--success"><span aria-hidden="true">✓</span> Registered</span>';
    } else if (full) {
      action = '<span class="status-pill status-pill--full">Course full</span>';
    } else {
      action = '<a class="btn btn--primary btn--small" href="registration.html?course=' +
        encodeURIComponent(course.id) +
        '" aria-label="Register for ' + escapeHTML(course.code + " " + course.title) + '">Register</a>';
    }

    const card = document.createElement("article");
    card.className = "course-card theme-" + theme;
    card.setAttribute("aria-labelledby", titleId);
    card.dataset.courseId = course.id;
    card.innerHTML =
      '<div class="course-card__top">' +
        '<span class="badge badge--department">' + escapeHTML(course.department) + "</span>" +
        '<span class="badge badge--level">' + course.level + " level</span>" +
      "</div>" +
      '<p class="course-card__code">' + escapeHTML(course.code) + " · " + course.credits + " credits</p>" +
      '<h3 class="course-card__title" id="' + titleId + '">' + escapeHTML(course.title) + "</h3>" +
      '<p class="course-card__description">' + escapeHTML(course.description) + "</p>" +
      '<ul class="course-card__meta" aria-label="Course details">' +
        "<li><span>Instructor</span><strong>" + escapeHTML(course.instructor) + "</strong></li>" +
        "<li><span>Schedule</span><strong>" + escapeHTML(formatSchedule(course)) + "</strong></li>" +
        "<li><span>Format</span><strong>" + escapeHTML(course.modality) + "</strong></li>" +
      "</ul>" +
      '<div class="course-card__footer">' +
        '<span class="' + seatClass + '">' + seatText + "</span>" +
        action +
      "</div>";

    return card;
  }

  function renderCourseCards(container, courses, options) {
    if (!container) {
      return;
    }

    const settings = options || {};
    const prefix = settings.idPrefix || "course";
    container.innerHTML = "";
    courses.forEach(function (course) {
      container.appendChild(createCourseCard(course, prefix));
    });
  }

  function renderRegistrationTable(tbody, options) {
    if (!tbody) {
      return;
    }

    const settings = options || {};
    const entries = getRegistrations();
    tbody.innerHTML = "";

    if (entries.length === 0) {
      const row = document.createElement("tr");
      const cell = document.createElement("td");
      cell.colSpan = 6;
      cell.innerHTML =
        '<div class="table-empty">' +
          "<p><strong>No courses registered yet.</strong></p>" +
          "<p>Find a course that sparks your curiosity and add it to your plan.</p>" +
          '<a class="btn btn--primary btn--small" href="catalog.html">Browse the course catalog</a>' +
        "</div>";
      row.appendChild(cell);
      tbody.appendChild(row);
      return;
    }

    entries.forEach(function (entry) {
      const course = getCourse(entry.courseId);
      if (!course) {
        return;
      }

      const row = document.createElement("tr");
      row.innerHTML =
        '<th scope="row" class="cell-course">' +
          '<span class="cell-course__title">' + escapeHTML(course.title) + "</span>" +
          '<span class="cell-course__code">' + escapeHTML(course.code) + "</span>" +
        "</th>" +
        "<td>" + escapeHTML(entry.term) + "</td>" +
        "<td>" + course.credits + "</td>" +
        "<td>" + escapeHTML(formatSchedule(course)) + "</td>" +
        "<td>" + escapeHTML(course.modality) + "</td>" +
        '<td class="cell-action">' +
          '<button type="button" class="btn btn--ghost btn--small btn--remove" data-remove-course="' + course.id + '" aria-label="Remove ' + escapeHTML(course.code + " " + course.title) + ' from your schedule">Remove</button>' +
        "</td>";
      tbody.appendChild(row);
    });

    tbody.onclick = function (event) {
      const button = event.target.closest("[data-remove-course]");
      if (!button) {
        return;
      }
      confirmRemove(button.dataset.removeCourse);
    };
  }

  function getNextClass() {
    const entries = getRegistrations()
      .map(function (entry) {
        return getCourse(entry.courseId);
      })
      .filter(function (course) {
        return course && course.days && course.days.length > 0;
      });

    if (entries.length === 0) {
      return null;
    }

    entries.sort(function (a, b) {
      const dayDifference = (DAY_ORDER[a.days[0]] || 99) - (DAY_ORDER[b.days[0]] || 99);
      if (dayDifference !== 0) {
        return dayDifference;
      }
      return a.time.localeCompare(b.time);
    });

    return entries[0];
  }

  function updateStats() {
    const entries = getRegistrations();
    const totalCredits = entries.reduce(function (sum, entry) {
      const course = getCourse(entry.courseId);
      return sum + (course ? course.credits : 0);
    }, 0);
    const nextClass = getNextClass();

    document.querySelectorAll('[data-stat="courses"]').forEach(function (element) {
      element.textContent = String(entries.length);
    });

    document.querySelectorAll('[data-stat="credits"]').forEach(function (element) {
      element.textContent = String(totalCredits);
    });

    document.querySelectorAll('[data-stat="next"]').forEach(function (element) {
      element.textContent = nextClass ? nextClass.code + " · " + nextClass.days[0] : "None yet";
    });
  }

  function showToast(message) {
    let toast = document.getElementById("appToast");

    if (!toast) {
      toast = document.createElement("div");
      toast.id = "appToast";
      toast.className = "toast";
      toast.setAttribute("role", "status");
      toast.setAttribute("aria-live", "polite");
      toast.setAttribute("aria-atomic", "true");
      document.body.appendChild(toast);
    }

    window.clearTimeout(toastTimer);
    toast.textContent = "";
    window.requestAnimationFrame(function () {
      toast.textContent = message;
      toast.classList.add("is-visible");
    });

    toastTimer = window.setTimeout(function () {
      toast.classList.remove("is-visible");
    }, 4200);
  }

  function ensureModal() {
    if (modal) {
      return modal;
    }

    modal = document.createElement("dialog");
    modal.className = "modal";
    modal.id = "appModal";
    modal.setAttribute("aria-labelledby", "appModalTitle");
    modal.setAttribute("aria-describedby", "appModalDescription");
    modal.innerHTML =
      '<div class="modal__card">' +
        '<button type="button" class="modal__close" data-modal-close aria-label="Close dialog">' +
          '<span aria-hidden="true">×</span>' +
        "</button>" +
        '<div class="modal__icon" data-modal-icon aria-hidden="true">✓</div>' +
        '<h2 id="appModalTitle" class="modal__title"></h2>' +
        '<p id="appModalDescription" class="modal__description"></p>' +
        '<dl class="modal__details" data-modal-details hidden></dl>' +
        '<div class="modal__actions">' +
          '<button type="button" class="btn btn--ghost" data-modal-secondary></button>' +
          '<button type="button" class="btn btn--primary" data-modal-primary></button>' +
        "</div>" +
      "</div>";

    document.body.appendChild(modal);

    modal.addEventListener("click", function (event) {
      if (event.target === modal) {
        modal.close();
      }
    });

    return modal;
  }

  function showModal(options) {
    const settings = Object.assign({
      title: "Notice",
      message: "",
      details: [],
      primaryLabel: "OK",
      secondaryLabel: "",
      onPrimary: null,
      onSecondary: null,
      tone: "success",
      icon: "✓"
    }, options || {});

    const dialog = ensureModal();
    const title = dialog.querySelector("#appModalTitle");
    const description = dialog.querySelector("#appModalDescription");
    const details = dialog.querySelector("[data-modal-details]");
    const icon = dialog.querySelector("[data-modal-icon]");
    const primary = dialog.querySelector("[data-modal-primary]");
    const secondary = dialog.querySelector("[data-modal-secondary]");
    const closeButton = dialog.querySelector("[data-modal-close]");

    dialog.dataset.tone = settings.tone;
    title.textContent = settings.title;
    description.textContent = settings.message;
    icon.textContent = settings.icon;

    details.innerHTML = "";
    if (settings.details && settings.details.length > 0) {
      settings.details.forEach(function (item) {
        const term = document.createElement("dt");
        const value = document.createElement("dd");
        term.textContent = item.label;
        value.textContent = item.value;
        details.appendChild(term);
        details.appendChild(value);
      });
      details.hidden = false;
    } else {
      details.hidden = true;
    }

    primary.textContent = settings.primaryLabel;
    primary.className = "btn " + (settings.tone === "danger" ? "btn--danger" : "btn--primary");

    if (settings.secondaryLabel) {
      secondary.textContent = settings.secondaryLabel;
      secondary.hidden = false;
    } else {
      secondary.hidden = true;
      secondary.textContent = "";
    }

    primary.onclick = function () {
      dialog.close();
      if (typeof settings.onPrimary === "function") {
        settings.onPrimary();
      }
    };

    secondary.onclick = function () {
      dialog.close();
      if (typeof settings.onSecondary === "function") {
        settings.onSecondary();
      }
    };

    closeButton.onclick = function () {
      dialog.close();
    };

    if (typeof dialog.showModal === "function") {
      dialog.showModal();
    } else {
      dialog.setAttribute("open", "");
    }

    window.requestAnimationFrame(function () {
      if (settings.tone === "danger" && !secondary.hidden) {
        secondary.focus();
      } else {
        primary.focus();
      }
    });
  }

  function confirmRemove(courseId) {
    const course = getCourse(courseId);
    const registration = getRegistrationFor(courseId);

    if (!course || !registration) {
      return;
    }

    showModal({
      tone: "danger",
      icon: "!",
      title: "Remove this course?",
      message: course.code + " — " + course.title + " will be removed from your registered courses.",
      details: [
        { label: "Term", value: registration.term },
        { label: "Credits", value: String(course.credits) },
        { label: "Schedule", value: formatSchedule(course) }
      ],
      primaryLabel: "Yes, remove course",
      secondaryLabel: "Keep course",
      onPrimary: function () {
        removeRegistration(courseId);
        updateStats();
        document.dispatchEvent(new CustomEvent("registrations:changed"));
        showToast(course.code + " was removed from your schedule.");
      }
    });
  }

  function setupNavigation() {
    const toggle = document.querySelector(".nav-toggle");
    const nav = document.getElementById("primaryNav");
    const header = document.querySelector(".site-header");
    const page = document.body.dataset.page;

    document.querySelectorAll("[data-nav]").forEach(function (link) {
      if (link.dataset.nav === page) {
        link.setAttribute("aria-current", "page");
      }
    });

    if (!toggle || !nav) {
      return;
    }

    function setOpen(open) {
      toggle.setAttribute("aria-expanded", open ? "true" : "false");
      nav.classList.toggle("is-open", open);
    }

    toggle.addEventListener("click", function () {
      const isOpen = toggle.getAttribute("aria-expanded") === "true";
      setOpen(!isOpen);
    });

    nav.addEventListener("click", function (event) {
      if (event.target.closest("a")) {
        setOpen(false);
      }
    });

    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && toggle.getAttribute("aria-expanded") === "true") {
        setOpen(false);
        toggle.focus();
      }
    });

    document.addEventListener("click", function (event) {
      if (toggle.getAttribute("aria-expanded") !== "true") {
        return;
      }
      if (header && !header.contains(event.target)) {
        setOpen(false);
      }
    });

    window.addEventListener("resize", function () {
      if (window.innerWidth > 860) {
        setOpen(false);
      }
    });
  }

  window.App = {
    courses: COURSES,
    terms: TERMS,
    emailPattern: EMAIL_PATTERN,
    escapeHTML: escapeHTML,
    getCourse: getCourse,
    getTheme: getTheme,
    getAvailableSeats: getAvailableSeats,
    isFull: isFull,
    formatSchedule: formatSchedule,
    getRegistrations: getRegistrations,
    getRegistrationFor: getRegistrationFor,
    isRegistered: isRegistered,
    addRegistration: addRegistration,
    removeRegistration: removeRegistration,
    loadProfile: loadProfile,
    saveProfile: saveProfile,
    getInitials: getInitials,
    renderCourseCards: renderCourseCards,
    renderRegistrationTable: renderRegistrationTable,
    updateStats: updateStats,
    showToast: showToast,
    showModal: showModal,
    confirmRemove: confirmRemove
  };

  setupNavigation();
})();

:root {
  --ink: #191c2b;
  --muted: #565b75;
  --surface: #ffffff;
  --bg: #faf9ff;
  --line: #e3def1;
  --brand: #6d28d9;
  --brand-dark: #4c1d95;
  --pink: #db2777;
  --orange: #ea580c;
  --green: #15803d;
  --red: #b91c1c;
  --yellow: #f59e0b;
  --radius: 22px;
  --shadow: 0 22px 50px -32px rgba(39, 22, 86, 0.5);
  --font: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  background:
    radial-gradient(1100px 540px at 8% -8%, #ede9fe 0%, rgba(237, 233, 254, 0) 62%),
    radial-gradient(900px 500px at 100% 2%, #fce7f3 0%, rgba(252, 231, 243, 0) 58%),
    var(--bg);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  max-width: 100%;
}

h1,
h2,
h3,
h4,
p {
  overflow-wrap: break-word;
}

h1,
h2,
h3,
h4 {
  color: var(--ink);
  line-height: 1.15;
}

a {
  color: var(--brand-dark);
}

button,
input,
select,
textarea {
  font: inherit;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 3px solid var(--yellow);
  outline-offset: 2px;
}

main:focus {
  outline: none;
}

.sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 1000;
  transform: translateY(-160%);
  padding: 0.8rem 1.1rem;
  border-radius: 12px;
  background: var(--ink);
  color: #fff;
  font-weight: 800;
  text-decoration: none;
  transition: transform 0.18s ease;
}

.skip-link:focus {
  transform: translateY(0);
}

/* Header and navigation */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  border-bottom: 1px solid rgba(227, 222, 241, 0.9);
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(16px);
}

.header-inner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: min(100%, 1220px);
  margin: 0 auto;
  padding: 0.7rem 1.25rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--ink);
  text-decoration: none;
  border-radius: 14px;
}

.brand-mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 46px;
  height: 46px;
  border-radius: 15px;
  background: linear-gradient(135deg, #7c3aed, #db2777 58%, #f97316);
  box-shadow: 0 10px 22px -12px rgba(124, 58, 237, 0.8);
  color: #fff;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.brand-text {
  display: flex;
  flex-direction: column;
  font-weight: 900;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
  line-height: 1.12;
}

.brand-text small {
  margin-top: 0.15rem;
  color: var(--muted);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.primary-nav ul {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.primary-nav a {
  display: inline-flex;
  align-items: center;
  min-height: 42px;
  padding: 0.55rem 0.9rem;
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.92rem;
  font-weight: 800;
  text-decoration: none;
  transition: background 0.15s ease, color 0.15s ease;
}

.primary-nav a:hover {
  background: #f3e8ff;
  color: var(--brand-dark);
}

.primary-nav a[aria-current="page"] {
  background: linear-gradient(135deg, #ede9fe, #fce7f3);
  box-shadow: inset 0 0 0 1px #ddd6fe;
  color: var(--brand-dark);
}

.nav-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: #fff;
  color: var(--ink);
  cursor: pointer;
}

.nav-toggle__bars,
.nav-toggle__bars::before,
.nav-toggle__bars::after {
  display: block;
  width: 20px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  content: "";
}

.nav-toggle__bars {
  position: relative;
}

.nav-toggle__bars::before {
  position: absolute;
  top: -6px;
  left: 0;
}

.nav-toggle__bars::after {
  position: absolute;
  top: 6px;
  left: 0;
}

/* Shared layout */
.section {
  width: min(100%, 1220px);
  margin: 0 auto;
  padding: 4rem 1.25rem 0;
}

.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1.25rem;
  flex-wrap: wrap;
  margin-bottom: 1.75rem;
}

.section-heading h2 {
  margin: 0.2rem 0 0;
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  letter-spacing: -0.035em;
}

.section-heading p {
  max-width: 62ch;
  margin: 0.55rem 0 0;
  color: var(--muted);
}

.kicker {
  margin: 0;
  color: var(--brand);
  font-size: 0.75rem;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.text-link {
  color: var(--brand-dark);
  font-weight: 800;
  text-underline-offset: 0.2em;
}

/* Hero */
.hero {
  width: min(100%, 1220px);
  margin: 1.5rem auto 0;
  padding: 0 1.25rem;
}

.hero__panel {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(280px, 0.88fr);
  align-items: center;
  gap: 2.5rem;
  overflow: hidden;
  padding: clamp(2rem, 5vw, 4.4rem);
  border-radius: 32px;
  background: linear-gradient(132deg, #4c1d95 0%, #7c3aed 45%, #db2777 100%);
  box-shadow: 0 34px 70px -42px rgba(76, 29, 149, 0.75);
  color: #fff;
}

.hero__panel::before {
  position: absolute;
  top: -32%;
  right: -12%;
  width: 480px;
  height: 480px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(253, 230, 138, 0.32), rgba(253, 230, 138, 0) 68%);
  content: "";
}

.hero__panel::after {
  position: absolute;
  bottom: -46%;
  left: 24%;
  width: 520px;
  height: 520px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0) 70%);
  content: "";
}

.hero__panel > * {
  position: relative;
  z-index: 1;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
  padding: 0.35rem 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.hero h1 {
  max-width: 15ch;
  margin: 0.9rem 0 1rem;
  color: #fff;
  font-size: clamp(2.35rem, 5vw, 4.25rem);
  letter-spacing: -0.05em;
  line-height: 1.01;
}

.hero h1 em {
  color: #fde68a;
  font-style: normal;
}

.hero__lead {
  max-width: 54ch;
  margin: 0;
  color: #f5f3ff;
  font-size: clamp(1rem, 1.4vw, 1.12rem);
}

.hero-search {
  display: flex;
  gap: 0.5rem;
  max-width: 620px;
  margin-top: 1.75rem;
  padding: 0.4rem;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 18px 40px -26px rgba(17, 10, 40, 0.85);
}

.hero-search input {
  flex: 1;
  min-width: 0;
  padding: 0.75rem 0.9rem;
  border: 0;
  border-radius: 12px;
  background: #fff;
  color: var(--ink);
}

.hero-search input::placeholder {
  color: #686d86;
  opacity: 1;
}

.hero__notes {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.2rem;
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
  color: #f5f3ff;
  font-size: 0.86rem;
  font-weight: 700;
}

.hero__notes li {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.hero__notes li::before {
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: rgba(253, 230, 138, 0.2);
  color: #fde68a;
  content: "✓";
  font-size: 0.7rem;
  font-weight: 900;
}

.hero-visual {
  display: grid;
  place-items: center;
  min-height: 340px;
}

.hero-orbit {
  position: absolute;
  width: min(360px, 92%);
  aspect-ratio: 1;
  border: 1px dashed rgba(255, 255, 255, 0.38);
  border-radius: 50%;
}

.hero-orbit::before,
.hero-orbit::after {
  position: absolute;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #fde68a;
  box-shadow: 0 0 0 6px rgba(253, 230, 138, 0.18);
  content: "";
}

.hero-orbit::before {
  top: 9%;
  right: 16%;
}

.hero-orbit::after {
  bottom: 13%;
  left: 8%;
  background: #f9a8d4;
  box-shadow: 0 0 0 6px rgba(249, 168, 212, 0.18);
}

.hero-stack {
  position: relative;
  display: grid;
  gap: 0.8rem;
  width: min(340px, 100%);
  transform: rotate(-2deg);
}

.mini-course {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  padding: 0.9rem 1rem;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.97);
  box-shadow: 0 18px 34px -22px rgba(17, 10, 40, 0.8);
  color: var(--ink);
}

.mini-course__mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  color: #fff;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.mini-course--violet .mini-course__mark {
  background: linear-gradient(135deg, #7c3aed, #a855f7);
}

.mini-course--orange .mini-course__mark {
  background: linear-gradient(135deg, #ea580c, #fb923c);
}

.mini-course--green .mini-course__mark {
  background: linear-gradient(135deg, #15803d, #4ade80);
}

.mini-course strong {
  display: block;
  font-size: 0.87rem;
  line-height: 1.25;
}

.mini-course span {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 700;
}

.mini-course__seats {
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  background: #dcfce7;
  color: #166534 !important;
  font-size: 0.68rem !important;
  font-weight: 900 !important;
  white-space: nowrap;
}

/* Stats */
.stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  width: min(100%, 1220px);
  margin: 2.25rem auto 0;
  padding: 0 1.25rem;
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  padding: 1.15rem 1.2rem;
  border: 1px solid var(--line);
  border-left: 5px solid #a855f7;
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow);
}

.stat-card:nth-child(2) {
  border-left-color: #ec4899;
}

.stat-card:nth-child(3) {
  border-left-color: #f97316;
}

.stat-card:nth-child(4) {
  border-left-color: #14b8a6;
}

.stat-card strong {
  display: block;
  color: var(--ink);
  font-size: 1.6rem;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.stat-card span {
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 700;
}

.stat-card__dot {
  display: grid;
  place-items: center;
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: #f3e8ff;
  color: #6d28d9;
  font-size: 1.1rem;
  font-weight: 900;
}

.stat-card:nth-child(2) .stat-card__dot {
  background: #fce7f3;
  color: #be185d;
}

.stat-card:nth-child(3) .stat-card__dot {
  background: #ffedd5;
  color: #c2410c;
}

.stat-card:nth-child(4) .stat-card__dot {
  background: #ccfbf1;
  color: #0f766e;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 44px;
  padding: 0.7rem 1.2rem;
  border: 2px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font-weight: 800;
  font-size: 0.9rem;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease, color 0.15s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn--primary {
  background: linear-gradient(135deg, #7c3aed, #db2777);
  box-shadow: 0 12px 26px -14px rgba(124, 58, 237, 0.8);
  color: #fff;
}

.btn--primary:hover {
  box-shadow: 0 16px 30px -14px rgba(219, 39, 119, 0.72);
}

.btn--secondary {
  border-color: #c4b5fd;
  background: #fff;
  color: var(--brand-dark);
}

.btn--secondary:hover {
  background: #f5f3ff;
}

.btn--ghost {
  border-color: transparent;
  color: #4b5069;
}

.btn--ghost:hover {
  background: #f3e8ff;
  color: var(--brand-dark);
}

.btn--light {
  background: #fff;
  color: var(--brand-dark);
  box-shadow: 0 12px 26px -16px rgba(17, 10, 40, 0.9);
}

.btn--light:hover {
  background: #fef3c7;
}

.btn--danger {
  background: #dc2626;
  color: #fff;
}

.btn--danger:hover {
  background: #b91c1c;
}

.btn--small {
  min-height: 38px;
  padding: 0.5rem 0.9rem;
  font-size: 0.8rem;
}

.btn--remove {
  color: #b91c1c;
}

.btn--remove:hover {
  background: #fee2e2;
  color: #991b1b;
}

/* Course cards */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(285px, 1fr));
  gap: 1.25rem;
}

.course-card {
  --accent: #7c3aed;
  --accent-soft: #f3e8ff;
  --accent-ink: #5b21b6;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  overflow: hidden;
  padding: 1.4rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: 0 16px 34px -30px rgba(39, 22, 86, 0.65);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.course-card::before {
  position: absolute;
  inset: 0 0 auto;
  height: 7px;
  background: var(--accent);
  content: "";
}

.course-card:hover {
  transform: translateY(-4px);
  border-color: #d5ccef;
  box-shadow: 0 24px 44px -28px rgba(39, 22, 86, 0.55);
}

.course-card__top {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  padding-top: 0.25rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.28rem 0.6rem;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.badge--department {
  background: var(--accent-soft);
  color: var(--accent-ink);
}

.badge--level {
  background: #f1f5f9;
  color: #334155;
}

.course-card__code {
  margin: 0;
  color: var(--accent-ink);
  font-size: 0.77rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.course-card__title {
  margin: 0;
  font-size: 1.3rem;
  letter-spacing: -0.025em;
  line-height: 1.2;
}

.course-card__description {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.course-card__meta {
  display: grid;
  gap: 0.4rem;
  margin: 0;
  padding: 0.8rem 0 0;
  border-top: 1px dashed var(--line);
  list-style: none;
}

.course-card__meta li {
  display: grid;
  grid-template-columns: 5.4rem minmax(0, 1fr);
  gap: 0.5rem;
  font-size: 0.82rem;
}

.course-card__meta span {
  color: var(--muted);
}

.course-card__meta strong {
  font-weight: 700;
}

.course-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: auto;
  padding-top: 0.85rem;
  border-top: 1px solid #f0edf8;
}

.seats {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  color: #166534;
  font-size: 0.78rem;
  font-weight: 800;
}

.seats::before {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #16a34a;
  box-shadow: 0 0 0 4px #dcfce7;
  content: "";
}

.seats--full {
  color: #b91c1c;
}

.seats--full::before {
  background: #dc2626;
  box-shadow: 0 0 0 4px #fee2e2;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.4rem 0.75rem;
  border-radius: 999px;
  font-size: 0.76rem;
  font-weight: 900;
  white-space: nowrap;
}

.status-pill--success {
  background: #dcfce7;
  color: #166534;
}

.status-pill--full {
  background: #fee2e2;
  color: #991b1b;
}

/* Colour themes */
.theme-violet {
  --accent: #7c3aed;
  --accent-soft: #f3e8ff;
  --accent-ink: #5b21b6;
}

.theme-blue {
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --accent-ink: #1e40af;
}

.theme-green {
  --accent: #15803d;
  --accent-soft: #dcfce7;
  --accent-ink: #166534;
}

.theme-pink {
  --accent: #db2777;
  --accent-soft: #fce7f3;
  --accent-ink: #9d174d;
}

.theme-orange {
  --accent: #ea580c;
  --accent-soft: #ffedd5;
  --accent-ink: #9a3412;
}

.theme-amber {
  --accent: #b45309;
  --accent-soft: #fef3c7;
  --accent-ink: #92400e;
}

.theme-teal {
  --accent: #0f766e;
  --accent-soft: #ccfbf1;
  --accent-ink: #115e59;
}

.theme-fuchsia {
  --accent: #c026d3;
  --accent-soft: #fae8ff;
  --accent-ink: #86198f;
}

.theme-rose {
  --accent: #e11d48;
  --accent-soft: #ffe4e6;
  --accent-ink: #9f1239;
}

.theme-indigo {
  --accent: #4338ca;
  --accent-soft: #e0e7ff;
  --accent-ink: #3730a3;
}

/* Steps and CTA */
.steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.25rem;
}

.step-card {
  position: relative;
  overflow: hidden;
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
}

.step-card::after {
  position: absolute;
  right: -34px;
  bottom: -42px;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: #faf5ff;
  content: "";
}

.step-card > * {
  position: relative;
  z-index: 1;
}

.step-number {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin-bottom: 1rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #7c3aed, #db2777);
  color: #fff;
  font-size: 1.05rem;
  font-weight: 900;
}

.step-card:nth-child(2) .step-number {
  background: linear-gradient(135deg, #0891b2, #2563eb);
}

.step-card:nth-child(3) .step-number {
  background: linear-gradient(135deg, #ea580c, #db2777);
}

.step-card h3 {
  margin: 0 0 0.45rem;
  font-size: 1.15rem;
}

.step-card p {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.cta {
  width: min(100%, 1220px);
  margin: 4rem auto 0;
  padding: 0 1.25rem;
}

.cta__panel {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  overflow: hidden;
  padding: clamp(2rem, 5vw, 3.4rem);
  border-radius: 30px;
  background: linear-gradient(120deg, #f97316, #db2777 55%, #7c3aed);
  box-shadow: 0 30px 60px -38px rgba(219, 39, 119, 0.8);
  color: #fff;
}

.cta__panel::after {
  position: absolute;
  top: -70px;
  right: 10%;
  width: 260px;
  height: 260px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  content: "";
}

.cta__panel > * {
  position: relative;
  z-index: 1;
}

.cta h2 {
  margin: 0 0 0.4rem;
  color: #fff;
  font-size: clamp(1.7rem, 3.4vw, 2.6rem);
  letter-spacing: -0.035em;
}

.cta p {
  max-width: 58ch;
  margin: 0;
  color: #fff7ed;
}

/* Page hero */
.page-hero {
  width: min(100%, 1220px);
  margin: 1.5rem auto 0;
  padding: 0 1.25rem;
}

.page-hero__panel {
  position: relative;
  overflow: hidden;
  padding: clamp(1.8rem, 4vw, 3rem);
  border: 1px solid #e9d5ff;
  border-radius: 28px;
  background: linear-gradient(120deg, #ede9fe 0%, #fce7f3 58%, #ffedd5 100%);
}

.page-hero__panel::after {
  position: absolute;
  top: -90px;
  right: -40px;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.45);
  content: "";
}

.page-hero__panel > * {
  position: relative;
  z-index: 1;
}

.page-hero h1 {
  max-width: 22ch;
  margin: 0.35rem 0 0.65rem;
  font-size: clamp(2rem, 4vw, 3.2rem);
  letter-spacing: -0.045em;
}

.page-hero p {
  max-width: 68ch;
  margin: 0;
  color: #4b5069;
}

/* Catalog */
.catalog-section {
  width: min(100%, 1220px);
  margin: 0 auto;
  padding: 2rem 1.25rem 0;
}

.filters-card {
  padding: 1.3rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
}

.filters-form {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1rem;
  align-items: end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  min-width: 0;
}

.field--search {
  grid-column: 1 / -1;
}

.field--full {
  grid-column: 1 / -1;
}

.field label,
.field-label {
  color: #343a52;
  font-size: 0.82rem;
  font-weight: 800;
}

.field .hint {
  margin: 0;
  color: var(--muted);
  font-size: 0.78rem;
}

.req {
  color: #be123c;
  font-weight: 900;
}

input[type="text"],
input[type="search"],
input[type="email"],
input[type="password"],
select,
textarea {
  width: 100%;
  min-height: 46px;
  padding: 0.68rem 0.85rem;
  border: 2px solid #d9d4ea;
  border-radius: 12px;
  background: #fff;
  color: var(--ink);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

textarea {
  min-height: 120px;
  resize: vertical;
}

input:hover,
select:hover,
textarea:hover {
  border-color: #bdb3dc;
}

input:focus,
select:focus,
textarea:focus {
  border-color: #7c3aed;
  box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.13);
}

input[aria-invalid="true"],
select[aria-invalid="true"],
textarea[aria-invalid="true"] {
  border-color: #dc2626;
  background: #fff7f7;
}

.field-error {
  margin: 0;
  color: #b91c1c;
  font-size: 0.8rem;
  font-weight: 800;
}

.results-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin: 1.5rem 0 1rem;
}

.results-count {
  margin: 0;
  color: #4b5069;
  font-size: 0.9rem;
  font-weight: 800;
}

.empty-state {
  padding: 3rem 1.5rem;
  border: 2px dashed #d8d0ef;
  border-radius: 24px;
  background: #fff;
  text-align: center;
}

.empty-state__icon {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin: 0 auto 1rem;
  border-radius: 50%;
  background: #f3e8ff;
  color: #6d28d9;
  font-size: 1.6rem;
  font-weight: 900;
}

.empty-state h2 {
  margin: 0 0 0.5rem;
  font-size: 1.35rem;
}

.empty-state p {
  max-width: 50ch;
  margin: 0 auto 1.25rem;
  color: var(--muted);
}

/* Registration */
.registration-section,
.profile-section {
  width: min(100%, 1220px);
  margin: 0 auto;
  padding: 2rem 1.25rem 0;
}

.registration-layout,
.profile-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.72fr);
  gap: 1.5rem;
  align-items: start;
}

.panel {
  padding: clamp(1.3rem, 3vw, 2rem);
  border: 1px solid var(--line);
  border-radius: 24px;
  background: #fff;
  box-shadow: var(--shadow);
}

.panel > h2 {
  margin: 0 0 0.35rem;
  font-size: 1.5rem;
  letter-spacing: -0.025em;
}

.panel__intro {
  margin: 0 0 1.5rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.registration-form fieldset {
  margin: 0 0 1.6rem;
  padding: 0;
  border: 0;
}

.registration-form fieldset:last-of-type {
  margin-bottom: 0.5rem;
}

.registration-form legend {
  margin-bottom: 0.25rem;
  padding: 0;
  color: var(--ink);
  font-size: 1.03rem;
  font-weight: 900;
}

.form-section__intro {
  margin: 0 0 1rem;
  color: var(--muted);
  font-size: 0.84rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.checkbox-field {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  padding: 0.85rem;
  border: 2px solid #e5e0f2;
  border-radius: 14px;
  background: #faf9ff;
}

.checkbox-field input {
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  min-height: 0;
  margin: 0.15rem 0 0;
  accent-color: #7c3aed;
}

.checkbox-field label {
  color: #343a52;
  font-size: 0.87rem;
  font-weight: 600;
}

.error-summary {
  margin-bottom: 1.25rem;
  padding: 1rem 1.15rem;
  border: 2px solid #fca5a5;
  border-radius: 16px;
  background: #fff1f2;
  color: #881337;
}

.error-summary h2 {
  margin: 0 0 0.45rem;
  color: #9f1239;
  font-size: 1rem;
}

.error-summary ul {
  margin: 0;
  padding-left: 1.2rem;
}

.error-summary a {
  color: #9f1239;
  font-weight: 800;
  text-underline-offset: 0.15em;
}

.form-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: 1.5rem;
  padding-top: 1.25rem;
  border-top: 1px solid #f0edf8;
}

.form-note {
  margin: 0.75rem 0 0;
  color: var(--muted);
  font-size: 0.78rem;
}

.course-preview {
  margin-top: 1rem;
  padding: 1rem 1.1rem;
  border: 1px solid #ddd6fe;
  border-radius: 16px;
  background: linear-gradient(135deg, #faf5ff, #fdf2f8);
}

.course-preview h3 {
  margin: 0 0 0.2rem;
  font-size: 1.02rem;
}

.course-preview__code {
  margin: 0 0 0.7rem;
  color: var(--brand-dark);
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.course-preview__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem 0.9rem;
  margin: 0;
  font-size: 0.82rem;
}

.course-preview__grid div {
  display: grid;
  gap: 0.05rem;
}

.course-preview__grid dt {
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
}

.course-preview__grid dd {
  margin: 0;
  font-weight: 700;
}

.plan-card {
  position: sticky;
  top: 96px;
  overflow: hidden;
  padding: 1.6rem;
  border-radius: 24px;
  background: linear-gradient(150deg, #2e1065, #5b21b6 56%, #9d174d);
  box-shadow: 0 28px 54px -36px rgba(46, 16, 101, 0.9);
  color: #fff;
}

.plan-card h2 {
  margin: 0;
  color: #fff;
  font-size: 1.35rem;
}

.plan-card > p {
  margin: 0.35rem 0 0;
  color: #ede9fe;
  font-size: 0.85rem;
}

.plan-card__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
  margin: 1.25rem 0;
}

.plan-stat {
  padding: 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.12);
}

.plan-stat strong {
  display: block;
  font-size: 1.45rem;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.plan-stat span {
  color: #ede9fe;
  font-size: 0.72rem;
  font-weight: 700;
}

.checklist {
  display: grid;
  gap: 0.6rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
  color: #ede9fe;
  font-size: 0.84rem;
}

.checklist li {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
}

.checklist li::before {
  color: #fde68a;
  content: "✓";
  font-weight: 900;
}

/* Tables */
.registered-section {
  width: min(100%, 1220px);
  margin: 2.5rem auto 0;
  padding: 0 1.25rem;
}

.table-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
}

.table-scroll {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
}

.data-table caption {
  padding: 1.1rem 1.25rem 0.25rem;
  color: #343a52;
  font-size: 0.92rem;
  font-weight: 900;
  text-align: left;
}

.data-table th,
.data-table td {
  padding: 0.9rem 1rem;
  border-bottom: 1px solid #eeeaf7;
  font-size: 0.88rem;
  text-align: left;
  vertical-align: middle;
}

.data-table thead th {
  border-bottom: 1px solid #e4def5;
  background: #f7f4ff;
  color: #5b5675;
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.data-table tbody tr:last-child th,
.data-table tbody tr:last-child td {
  border-bottom: 0;
}

.data-table tbody tr:hover {
  background: #fcfbff;
}

.cell-course__title {
  display: block;
  color: var(--ink);
  font-weight: 800;
}

.cell-course__code {
  display: block;
  margin-top: 0.12rem;
  color: #6b6685;
  font-size: 0.74rem;
  font-weight: 800;
}

.cell-action {
  text-align: right;
}

.table-empty {
  max-width: 430px;
  margin: 0 auto;
  padding: 2rem 1rem;
  color: var(--muted);
  text-align: center;
}

.table-empty p {
  margin: 0.3rem 0;
}

.table-empty .btn {
  margin-top: 0.75rem;
}

/* Profile */
.profile-hero-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 1.25rem;
  flex-wrap: wrap;
  overflow: hidden;
  margin-bottom: 1.5rem;
  padding: 1.6rem;
  border: 1px solid var(--line);
  border-radius: 26px;
  background: #fff;
  box-shadow: var(--shadow);
}

.profile-hero-card::after {
  position: absolute;
  top: -80px;
  right: -30px;
  width: 240px;
  height: 240px;
  border-radius: 50%;
  background: linear-gradient(135deg, #f3e8ff, #fce7f3);
  content: "";
}

.profile-hero-card > * {
  position: relative;
  z-index: 1;
}

.avatar {
  display: grid;
  place-items: center;
  flex: none;
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: linear-gradient(135deg, #7c3aed, #db2777 62%, #f97316);
  box-shadow: 0 18px 30px -18px rgba(124, 58, 237, 0.9);
  color: #fff;
  font-size: 1.75rem;
  font-weight: 900;
  letter-spacing: -0.03em;
}

.profile-hero-card h2 {
  margin: 0;
  font-size: 1.6rem;
  letter-spacing: -0.03em;
}

.profile-meta {
  margin: 0.25rem 0 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.profile-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-top: 0.75rem;
}

.profile-tags span {
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  background: #f3e8ff;
  color: #5b21b6;
  font-size: 0.7rem;
  font-weight: 900;
}

.profile-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.snapshot-card {
  padding: 1.5rem;
  border: 1px solid #dbeafe;
  border-radius: 24px;
  background: linear-gradient(150deg, #ecfeff, #eef2ff 52%, #fdf2f8);
}

.snapshot-card h2 {
  margin: 0 0 0.3rem;
  font-size: 1.2rem;
}

.snapshot-card > p {
  margin: 0 0 0.8rem;
  color: var(--muted);
  font-size: 0.84rem;
}

.snapshot-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.snapshot-list li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.6rem 0;
  border-bottom: 1px dashed #c7d2fe;
  font-size: 0.84rem;
}

.snapshot-list li:last-child {
  border-bottom: 0;
}

.snapshot-list span {
  color: var(--muted);
}

.snapshot-list strong {
  text-align: right;
}

/* Footer */
.site-footer {
  margin-top: 4.5rem;
  padding: 3rem 1.25rem 2rem;
  background: #1c1330;
  color: #e9e4f5;
}

.footer-inner {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 2rem;
  width: min(100%, 1220px);
  margin: 0 auto;
}

.footer-brand .brand {
  color: #fff;
}

.footer-brand .brand-text small {
  color: #c4b5fd;
}

.footer-brand p {
  max-width: 36ch;
  margin: 1rem 0 0;
  color: #c9c0e2;
  font-size: 0.86rem;
}

.footer-inner h2 {
  margin: 0 0 0.75rem;
  color: #fff;
  font-size: 0.8rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.footer-links {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.footer-links a {
  color: #ddd6fe;
  font-size: 0.88rem;
  text-underline-offset: 0.2em;
}

.footer-links a:hover {
  color: #fff;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  width: min(100%, 1220px);
  margin: 2.5rem auto 0;
  padding-top: 1.25rem;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
  color: #b9aed6;
  font-size: 0.78rem;
}

/* Modal */
.modal {
  width: min(92vw, 520px);
  max-width: 520px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
}

.modal::backdrop {
  background: rgba(20, 12, 40, 0.64);
  backdrop-filter: blur(4px);
}

.modal__card {
  position: relative;
  padding: clamp(1.5rem, 4vw, 2.2rem);
  border-radius: 26px;
  background: #fff;
  box-shadow: 0 40px 90px -30px rgba(20, 12, 40, 0.65);
  animation: modal-in 0.2s ease-out;
}

.modal__close {
  position: absolute;
  top: 0.9rem;
  right: 0.9rem;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: #fff;
  color: #4b5069;
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
}

.modal__close:hover {
  background: #f3e8ff;
  color: var(--brand-dark);
}

.modal__icon {
  display: grid;
  place-items: center;
  width: 60px;
  height: 60px;
  margin-bottom: 1rem;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  font-size: 1.5rem;
  font-weight: 900;
}

.modal[data-tone="danger"] .modal__icon {
  background: #fee2e2;
  color: #b91c1c;
}

.modal__title {
  margin: 0 0 0.5rem;
  font-size: 1.5rem;
  letter-spacing: -0.03em;
}

.modal__description {
  margin: 0 0 1rem;
  color: var(--muted);
}

.modal__details {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.45rem 0.9rem;
  margin: 1rem 0 0;
  padding: 1rem;
  border-radius: 14px;
  background: #faf9ff;
  font-size: 0.86rem;
}

.modal__details dt {
  color: var(--muted);
  font-weight: 800;
}

.modal__details dd {
  margin: 0;
  font-weight: 800;
  text-align: right;
}

.modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.7rem;
  flex-wrap: wrap;
  margin-top: 1.35rem;
}

.modal__actions .btn {
  flex: 1 1 auto;
}

@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: 1.5rem;
  z-index: 300;
  max-width: min(92vw, 480px);
  padding: 0.85rem 1.15rem;
  border-left: 5px solid #34d399;
  border-radius: 14px;
  background: #1c1330;
  box-shadow: 0 22px 40px -20px rgba(17, 10, 40, 0.8);
  color: #fff;
  font-size: 0.88rem;
  font-weight: 800;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 130%);
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

@media (prefers-reduced-motion: no-preference) {
  .hero-stack {
    animation: hero-float 6s ease-in-out infinite;
  }

  .hero-stack .mini-course:nth-child(2) {
    animation: mini-bob 5s ease-in-out infinite;
  }

  .hero-stack .mini-course:nth-child(3) {
    animation: mini-bob 5.6s ease-in-out 0.4s infinite;
  }
}

@keyframes hero-float {
  0%,
  100% {
    transform: rotate(-2deg) translateY(0);
  }
  50% {
    transform: rotate(-2deg) translateY(-8px);
  }
}

@keyframes mini-bob {
  0%,
  100% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(5px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Responsive */
@media (max-width: 1040px) {
  .stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .registration-layout,
  .profile-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .plan-card {
    position: static;
  }
}

@media (max-width: 900px) {
  .hero__panel {
    grid-template-columns: minmax(0, 1fr);
  }

  .hero-visual {
    display: none;
  }

  .filters-form {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .steps {
    grid-template-columns: minmax(0, 1fr);
  }

  .footer-inner {
    grid-template-columns: 1.3fr 1fr 1fr;
  }
}

@media (max-width: 860px) {
  .nav-toggle {
    display: inline-flex;
  }

  .primary-nav {
    position: absolute;
    top: calc(100% + 0.45rem);
    right: 1rem;
    left: 1rem;
    display: none;
    padding: 0.65rem;
    border: 1px solid var(--line);
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 24px 50px -26px rgba(39, 22, 86, 0.6);
  }

  .primary-nav.is-open {
    display: block;
  }

  .primary-nav ul {
    align-items: stretch;
    flex-direction: column;
    gap: 0.2rem;
  }

  .primary-nav a {
    display: flex;
    padding: 0.8rem 1rem;
    border-radius: 12px;
  }
}

@media (max-width: 720px) {
  .form-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .profile-stats {
    grid-template-columns: minmax(0, 1fr);
  }

  .footer-inner {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .data-table caption {
    padding: 1rem 1rem 0.25rem;
  }
}

@media (max-width: 620px) {
  .header-inner {
    padding: 0.65rem 1rem;
  }

  .brand-text small {
    display: none;
  }

  .hero {
    margin-top: 1rem;
    padding: 0 1rem;
  }

  .hero__panel {
    border-radius: 24px;
  }

  .hero-search {
    flex-direction: column;
  }

  .hero-search .btn {
    width: 100%;
  }

  .stats {
    grid-template-columns: minmax(0, 1fr);
    padding: 0 1rem;
  }

  .section {
    padding: 3rem 1rem 0;
  }

  .catalog-section,
  .registration-section,
  .profile-section,
  .registered-section,
  .page-hero {
    padding-right: 1rem;
    padding-left: 1rem;
  }

  .cta {
    margin-top: 3rem;
    padding: 0 1rem;
  }

  .filters-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .course-preview__grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .profile-hero-card {
    align-items: flex-start;
  }

  .modal__actions {
    flex-direction: column-reverse;
  }

  .modal__actions .btn {
    width: 100%;
  }
}

@media (max-width: 420px) {
  .brand-mark {
    width: 42px;
    height: 42px;
  }

  .brand-text {
    font-size: 0.98rem;
  }

  .course-card {
    padding: 1.2rem;
  }

  .footer-inner {
    grid-template-columns: minmax(0, 1fr);
  }

  .footer-brand {
    grid-column: auto;
  }
}

(function () {
  "use strict";

