    })
    .filter(Boolean);

  window.App.renderCourseCards(container, featuredCourses, { idPrefix: "featured" });
})();

(function () {
  "use strict";

  const grid = document.getElementById("courseGrid");
  if (!grid || !window.App) {
    return;
  }

  const courses = window.App.courses;
  const form = document.getElementById("catalogFilters");
  const searchInput = document.getElementById("catalogSearch");
  const deptFilter = document.getElementById("deptFilter");
  const levelFilter = document.getElementById("levelFilter");
  const modalityFilter = document.getElementById("modalityFilter");
  const dayFilter = document.getElementById("dayFilter");
  const sortFilter = document.getElementById("sortFilter");
  const resultsCount = document.getElementById("resultsCount");
  const emptyState = document.getElementById("emptyState");
  const clearButton = document.getElementById("clearFilters");
  const emptyReset = document.getElementById("emptyReset");

  let searchTimer = null;

  function addOptions(select, values) {
    values.forEach(function (value) {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = value;
      select.appendChild(option);
    });
  }

  function populateFilters() {
    const departments = Array.from(new Set(courses.map(function (course) {
      return course.department;
    }))).sort();

    const levels = Array.from(new Set(courses.map(function (course) {
      return String(course.level);
    }))).sort(function (a, b) {
      return Number(a) - Number(b);
    });

    const modalities = Array.from(new Set(courses.map(function (course) {
      return course.modality;
    }))).sort();

    const fixedDays = ["Mon", "Tue", "Wed", "Thu", "Fri"];
    const days = fixedDays.filter(function (day) {
      return courses.some(function (course) {
        return course.days.indexOf(day) !== -1;
      });
    });

    if (courses.some(function (course) { return course.days.length === 0; })) {
      days.push("Self-paced");
    }

    addOptions(deptFilter, departments);
    addOptions(levelFilter, levels);
    addOptions(modalityFilter, modalities);
    addOptions(dayFilter, days);
  }

  function setSelectValue(select, value) {
    if (!value) {
      return;
    }
    const match = Array.from(select.options).some(function (option) {
      return option.value === value;
    });
    if (match) {
      select.value = value;
    }
  }

  function applyQueryParams() {
    const params = new URLSearchParams(window.location.search);
    if (params.get("q")) {
      searchInput.value = params.get("q");
    }
    setSelectValue(deptFilter, params.get("dept"));
    setSelectValue(levelFilter, params.get("level"));
    setSelectValue(modalityFilter, params.get("modality"));
    setSelectValue(dayFilter, params.get("day"));
    setSelectValue(sortFilter, params.get("sort"));
  }

  function readFilters() {
    return {
      query: searchInput.value.trim().toLowerCase(),
      department: deptFilter.value,
      level: levelFilter.value,
      modality: modalityFilter.value,
      day: dayFilter.value,
      sort: sortFilter.value
    };
  }

  function matchesFilters(course, filters) {
    if (filters.department && course.department !== filters.department) {
      return false;
    }

    if (filters.level && String(course.level) !== filters.level) {
      return false;
    }

    if (filters.modality && course.modality !== filters.modality) {
      return false;
    }

    if (filters.day === "Self-paced" && course.days.length !== 0) {
      return false;
    }

    if (filters.day && filters.day !== "Self-paced" && course.days.indexOf(filters.day) === -1) {
      return false;
    }

    if (filters.query) {
      const haystack = [
        course.code,
        course.title,
        course.department,
        course.instructor,
        course.description,
        course.modality,
        course.tags.join(" ")
      ].join(" ").toLowerCase();

      const tokens = filters.query.split(/\s+/).filter(Boolean);
      const everyTokenMatches = tokens.every(function (token) {
        return haystack.indexOf(token) !== -1;
      });

      if (!everyTokenMatches) {
        return false;
      }
    }

    return true;
  }

  function sortCourses(list, sortValue) {
    const sorted = list.slice();

    if (sortValue === "code") {
      sorted.sort(function (a, b) {
        return a.code.localeCompare(b.code);
      });
    } else if (sortValue === "title") {
      sorted.sort(function (a, b) {
        return a.title.localeCompare(b.title);
      });
    } else if (sortValue === "credits") {
      sorted.sort(function (a, b) {
        return b.credits - a.credits || a.code.localeCompare(b.code);
      });
    } else if (sortValue === "seats") {
      sorted.sort(function (a, b) {
        return window.App.getAvailableSeats(b) - window.App.getAvailableSeats(a) || a.code.localeCompare(b.code);
      });
    }

    return sorted;
  }

  function updateUrl(filters) {
    const params = new URLSearchParams();
    if (filters.query) {
      params.set("q", searchInput.value.trim());
    }
    if (filters.department) {
      params.set("dept", filters.department);
    }
    if (filters.level) {
      params.set("level", filters.level);
    }
    if (filters.modality) {
      params.set("modality", filters.modality);
    }
    if (filters.day) {
      params.set("day", filters.day);
    }
    if (filters.sort && filters.sort !== "recommended") {
      params.set("sort", filters.sort);
    }

    const query = params.toString();
    const newUrl = window.location.pathname + (query ? "?" + query : "");

    try {
      window.history.replaceState(null, "", newUrl);
    } catch (error) {
      /* Some file:// contexts block history updates; filtering still works. */
    }
  }

  function applyFilters() {
    const filters = readFilters();
    const filtered = courses.filter(function (course) {
      return matchesFilters(course, filters);
    });
    const sorted = sortCourses(filtered, filters.sort);

    window.App.renderCourseCards(grid, sorted, { idPrefix: "catalog" });

    grid.hidden = sorted.length === 0;
    emptyState.hidden = sorted.length !== 0;

    if (sorted.length === 0) {
      resultsCount.textContent = "No courses found";
    } else if (sorted.length === courses.length) {
      resultsCount.textContent = "Showing all " + courses.length + " courses";
    } else {
      resultsCount.textContent = "Showing " + sorted.length + " of " + courses.length + " courses";
    }

    updateUrl(filters);
  }

  function resetFilters() {
    searchInput.value = "";
    deptFilter.value = "";
    levelFilter.value = "";
    modalityFilter.value = "";
    dayFilter.value = "";
    sortFilter.value = "recommended";
    applyFilters();
    searchInput.focus();
  }

  populateFilters();
  applyQueryParams();

  if (form) {
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      window.clearTimeout(searchTimer);
      applyFilters();
    });
  }

  if (searchInput) {
    searchInput.addEventListener("input", function () {
      window.clearTimeout(searchTimer);
      searchTimer = window.setTimeout(applyFilters, 140);
    });
  }

  [deptFilter, levelFilter, modalityFilter, dayFilter, sortFilter].forEach(function (select) {
    if (select) {
      select.addEventListener("change", function () {
        window.clearTimeout(searchTimer);
        applyFilters();
      });
    }
  });

  if (clearButton) {
    clearButton.addEventListener("click", resetFilters);
  }

  if (emptyReset) {
    emptyReset.addEventListener("click", resetFilters);
  }

  applyFilters();
})();

(function () {
  "use strict";

  const form = document.getElementById("registrationForm");
  if (!form || !window.App) {
    return;
  }

  const fullName = document.getElementById("fullName");
  const studentId = document.getElementById("studentId");
  const email = document.getElementById("email");
  const courseSelect = document.getElementById("courseSelect");
  const termSelect = document.getElementById("termSelect");
  const notes = document.getElementById("notes");
  const consent = document.getElementById("consent");

  const errorSummary = document.getElementById("formErrors");
  const errorList = document.getElementById("formErrorList");
  const preview = document.getElementById("coursePreview");
  const previewTitle = document.getElementById("coursePreviewTitle");
  const previewCode = document.getElementById("coursePreviewCode");
  const previewInstructor = document.getElementById("coursePreviewInstructor");
  const previewSchedule = document.getElementById("coursePreviewSchedule");
  const previewFormat = document.getElementById("coursePreviewFormat");
  const previewSeats = document.getElementById("coursePreviewSeats");
  const tableBody = document.getElementById("registrationTableBody");

  const fields = [fullName, studentId, email, courseSelect, termSelect, consent];

  const errorElements = {
    fullName: document.getElementById("fullName-error"),
    studentId: document.getElementById("studentId-error"),
    email: document.getElementById("email-error"),
    courseSelect: document.getElementById("course-error"),
    termSelect: document.getElementById("term-error"),
    consent: document.getElementById("consent-error")
  };

  let profile = window.App.loadProfile();

  function prefillStudentDetails() {
    fullName.value = profile.name || "";
    studentId.value = profile.studentId || "";
    email.value = profile.email || "";
  }

  function populateTerms() {
    const current = termSelect.value;
    while (termSelect.options.length > 1) {
      termSelect.remove(1);
    }

    window.App.terms.forEach(function (term) {
      const option = document.createElement("option");
      option.value = term.name;
      option.textContent = term.name + (term.status === "Waitlist" ? " (waitlist)" : "");
      termSelect.appendChild(option);
    });

    if (current) {
      termSelect.value = current;
    } else if (window.App.terms.length > 0) {
      termSelect.value = window.App.terms[0].name;
    }
  }

  function populateCourses() {
    const current = courseSelect.value;

    while (courseSelect.options.length > 1) {
      courseSelect.remove(1);
    }

    const grouped = {};
    window.App.courses
      .slice()
      .sort(function (a, b) {
        return a.department.localeCompare(b.department) || a.code.localeCompare(b.code);
      })
      .forEach(function (course) {
        if (!grouped[course.department]) {
          grouped[course.department] = [];
        }
        grouped[course.department].push(course);
      });

    Object.keys(grouped).forEach(function (department) {
      const group = document.createElement("optgroup");
      group.label = department;

      grouped[department].forEach(function (course) {
        const registered = window.App.isRegistered(course.id);
        const full = window.App.isFull(course);
        const option = document.createElement("option");
        option.value = course.id;
        option.textContent = course.code + " — " + course.title + " (" + course.credits + " cr)";

        if (registered) {
          option.disabled = true;
          option.textContent += " — already registered";
        } else if (full) {
          option.disabled = true;
          option.textContent += " — course full";
        }

        group.appendChild(option);
      });

      courseSelect.appendChild(group);
    });

    if (current) {
      const selected = Array.from(courseSelect.options).find(function (option) {
        return option.value === current && !option.disabled;
      });
      courseSelect.value = selected ? current : "";
    }
  }

  function updatePreview() {
    const course = window.App.getCourse(courseSelect.value);

    if (!course) {
      preview.hidden = true;
      return;
    }

    const available = window.App.getAvailableSeats(course);

    previewTitle.textContent = course.title;
    previewCode.textContent = course.code + " · " + course.credits + " credits · " + course.department;
    previewInstructor.textContent = course.instructor;
    previewSchedule.textContent = window.App.formatSchedule(course);
    previewFormat.textContent = course.modality;
    previewSeats.textContent = available + " of " + course.seats + " seats available";
    preview.hidden = false;
  }

  function clearFieldError(field) {
    if (!field) {
      return;
    }
    field.removeAttribute("aria-invalid");
    const error = errorElements[field.id];
    if (error) {
      error.hidden = true;
      error.textContent = "";
    }
  }

  function clearAllErrors() {
    fields.forEach(clearFieldError);
    if (errorSummary) {
      errorSummary.hidden = true;
    }
    if (errorList) {
      errorList.innerHTML = "";
    }
  }

  function showErrors(errors) {
    clearAllErrors();

    errors.forEach(function (item) {
      if (item.field) {
        item.field.setAttribute("aria-invalid", "true");
        const error = errorElements[item.field.id];
        if (error) {
          error.textContent = item.message;
          error.hidden = false;
        }
      }

      if (errorList) {
        const listItem = document.createElement("li");
        const link = document.createElement("a");
        link.href = "#" + (item.field ? item.field.id : "registrationForm");
        link.textContent = item.message;
        listItem.appendChild(link);
        errorList.appendChild(listItem);
      }
    });

    if (errorSummary) {
      errorSummary.hidden = false;
      errorSummary.focus();
    }
  }

  function validate() {
    const errors = [];
    const nameValue = fullName.value.trim();
    const idValue = studentId.value.trim();
    const emailValue = email.value.trim();
    const courseValue = courseSelect.value;
    const course = window.App.getCourse(courseValue);
    const termValue = termSelect.value;

    if (!nameValue) {
      errors.push({ field: fullName, message: "Enter your full name." });
    } else if (nameValue.length < 2) {
      errors.push({ field: fullName, message: "Your full name must be at least 2 characters." });
    }

    if (!idValue) {
      errors.push({ field: studentId, message: "Enter your student ID." });
    } else if (!/^[A-Za-z0-9-]{4,}$/.test(idValue)) {
      errors.push({ field: studentId, message: "Use at least 4 letters, numbers, or hyphens for your student ID." });
    }

    if (!emailValue) {
      errors.push({ field: email, message: "Enter your university email address." });
    } else if (!window.App.emailPattern.test(emailValue)) {
      errors.push({ field: email, message: "Enter a valid email address, such as name@university.edu." });
    }

    if (!courseValue) {
      errors.push({ field: courseSelect, message: "Choose a course to register for." });
    } else if (!course) {
      errors.push({ field: courseSelect, message: "Choose a valid course from the list." });
    } else if (window.App.isRegistered(course.id)) {
      errors.push({ field: courseSelect, message: "You are already registered for this course." });
    } else if (window.App.isFull(course)) {
      errors.push({ field: courseSelect, message: "This course is full. Please choose another course." });
    }

    if (!termValue) {
      errors.push({ field: termSelect, message: "Choose a term." });
    } else if (!window.App.terms.some(function (term) { return term.name === termValue; })) {
      errors.push({ field: termSelect, message: "Choose a valid term from the list." });
    }

    if (!consent.checked) {
      errors.push({ field: consent, message: "Confirm that your details are correct before registering." });
    }

    return {
      errors: errors,
      values: {
        name: nameValue,
        studentId: idValue,
        email: emailValue,
        course: course,
        term: termValue,
        notes: notes.value.trim()
      }
    };
  }

  function renderTable() {
    window.App.renderRegistrationTable(tableBody);
  }

  function resetFormAfterRegistration() {
    courseSelect.value = "";
    notes.value = "";
    consent.checked = false;
    populateCourses();
    updatePreview();
    renderTable();
    window.App.updateStats();
  }

  function handleSubmit(event) {
    event.preventDefault();

    const result = validate();

    if (result.errors.length > 0) {
      showErrors(result.errors);
      return;
    }

    const values = result.values;
    const added = window.App.addRegistration(values.course.id, values.term);

    if (!added) {
      showErrors([{ field: courseSelect, message: "We could not add that course. Please choose another course." }]);
      return;
    }

    profile.name = values.name;
    profile.studentId = values.studentId;
    profile.email = values.email;
    window.App.saveProfile(profile);

    clearAllErrors();
    resetFormAfterRegistration();

    const prefersReducedMotion = window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    window.App.showModal({
      tone: "success",
      icon: "✓",
      title: "You are registered!",
      message: values.course.code + " — " + values.course.title + " has been added to your " + values.term + " schedule. A confirmation has been sent to " + values.email + ".",
      details: [
        { label: "Term", value: values.term },
        { label: "Credits", value: String(values.course.credits) },
        { label: "Instructor", value: values.course.instructor },
        { label: "Schedule", value: window.App.formatSchedule(values.course) }
      ],
      primaryLabel: "View my courses",
      secondaryLabel: "Register another course",
      onPrimary: function () {
        const heading = document.getElementById("registeredHeading");
        if (heading) {
          heading.scrollIntoView({ behavior: prefersReducedMotion ? "auto" : "smooth", block: "start" });
          heading.focus({ preventScroll: true });
        }
      },
      onSecondary: function () {
        courseSelect.focus();
      }
    });
  }

  prefillStudentDetails();
  populateTerms();
  populateCourses();

  const requestedCourse = new URLSearchParams(window.location.search).get("course");
  if (requestedCourse) {
    const matchingOption = Array.from(courseSelect.options).find(function (option) {
      return option.value === requestedCourse && !option.disabled;
    });
    if (matchingOption) {
      courseSelect.value = requestedCourse;
    }
  }

  updatePreview();
  renderTable();
  window.App.updateStats();

  form.addEventListener("submit", handleSubmit);

  fields.forEach(function (field) {
    if (!field) {
      return;
    }
    const eventName = field.type === "checkbox" || field.tagName === "SELECT" ? "change" : "input";
    field.addEventListener(eventName, function () {
      clearFieldError(field);
      if (errorSummary && !form.querySelector('[aria-invalid="true"]')) {
        errorSummary.hidden = true;
      }
    });
  });

  courseSelect.addEventListener("change", updatePreview);

  document.addEventListener("registrations:changed", function () {
    populateCourses();
    updatePreview();
    renderTable();
    window.App.updateStats();
  });
})();

(function () {
  "use strict";

  const form = document.getElementById("profileForm");
  if (!form || !window.App) {
    return;
  }

  const nameInput = document.getElementById("profileNameInput");
  const emailInput = document.getElementById("profileEmail");
  const idInput = document.getElementById("profileId");
  const programSelect = document.getElementById("programSelect");
  const yearSelect = document.getElementById("yearSelect");
  const pronounsInput = document.getElementById("pronouns");
  const interestsInput = document.getElementById("interests");
  const emailUpdates = document.getElementById("emailUpdates");
  const waitlistAlerts = document.getElementById("waitlistAlerts");

  const errorSummary = document.getElementById("profileErrors");
  const errorList = document.getElementById("profileErrorList");
  const status = document.getElementById("profileStatus");
  const tableBody = document.getElementById("profileTableBody");

  const avatar = document.getElementById("profileAvatar");
  const displayName = document.getElementById("profileName");
  const displayMeta = document.getElementById("profileMeta");
  const programTag = document.getElementById("profileProgramTag");
  const yearTag = document.getElementById("profileYearTag");
  const snapshotProgram = document.getElementById("snapshotProgram");
  const snapshotYear = document.getElementById("snapshotYear");
  const snapshotId = document.getElementById("snapshotId");

  const fields = [nameInput, emailInput, idInput, programSelect, yearSelect];

  const errorElements = {
    profileNameInput: document.getElementById("profileNameInput-error"),
    profileEmail: document.getElementById("profileEmail-error"),
    profileId: document.getElementById("profileId-error"),
    programSelect: document.getElementById("programSelect-error"),
    yearSelect: document.getElementById("yearSelect-error")
  };

  let profile = window.App.loadProfile();

  function optionExists(select, value) {
    return Array.from(select.options).some(function (option) {
      return option.value === value;
    });
  }

  function updateDisplay() {
    avatar.textContent = window.App.getInitials(profile.name);
    displayName.textContent = profile.name;
    displayMeta.textContent = profile.studentId + " · " + profile.program + " · " + profile.year;
    programTag.textContent = profile.program;
    yearTag.textContent = profile.year;
    snapshotProgram.textContent = profile.program;
    snapshotYear.textContent = profile.year;
    snapshotId.textContent = profile.studentId;
  }

  function fillForm() {
    nameInput.value = profile.name || "";
    emailInput.value = profile.email || "";
    idInput.value = profile.studentId || "";
    pronounsInput.value = profile.pronouns || "";
    interestsInput.value = profile.interests || "";
    emailUpdates.checked = Boolean(profile.emailUpdates);
    waitlistAlerts.checked = Boolean(profile.waitlistAlerts);

    if (profile.program && optionExists(programSelect, profile.program)) {
      programSelect.value = profile.program;
    }

    if (profile.year && optionExists(yearSelect, profile.year)) {
      yearSelect.value = profile.year;
    }
  }

  function clearFieldError(field) {
    if (!field) {
      return;
    }
    field.removeAttribute("aria-invalid");
    const error = errorElements[field.id];
    if (error) {
      error.hidden = true;
      error.textContent = "";
    }
  }

  function clearAllErrors() {
    fields.forEach(clearFieldError);
    if (errorSummary) {
      errorSummary.hidden = true;
    }
    if (errorList) {
      errorList.innerHTML = "";
    }
  }

  function showErrors(errors) {
    clearAllErrors();

    errors.forEach(function (item) {
      item.field.setAttribute("aria-invalid", "true");
      const error = errorElements[item.field.id];
      if (error) {
        error.textContent = item.message;
        error.hidden = false;
      }

      if (errorList) {
        const listItem = document.createElement("li");
        const link = document.createElement("a");
        link.href = "#" + item.field.id;
        link.textContent = item.message;
        listItem.appendChild(link);
        errorList.appendChild(listItem);
      }
    });

    if (errorSummary) {
      errorSummary.hidden = false;
      errorSummary.focus();
    }
  }

  function validateProfile() {
    const errors = [];
    const name = nameInput.value.trim();
    const email = emailInput.value.trim();
    const studentId = idInput.value.trim();

    if (!name) {
      errors.push({ field: nameInput, message: "Enter your full name." });
    } else if (name.length < 2) {
      errors.push({ field: nameInput, message: "Your full name must be at least 2 characters." });
    }

    if (!email) {
      errors.push({ field: emailInput, message: "Enter your university email address." });
    } else if (!window.App.emailPattern.test(email)) {
      errors.push({ field: emailInput, message: "Enter a valid email address, such as name@university.edu." });
    }

    if (!studentId) {
      errors.push({ field: idInput, message: "Enter your student ID." });
    } else if (!/^[A-Za-z0-9-]{4,}$/.test(studentId)) {
      errors.push({ field: idInput, message: "Use at least 4 letters, numbers, or hyphens for your student ID." });
    }

    if (!programSelect.value || !optionExists(programSelect, programSelect.value)) {
      errors.push({ field: programSelect, message: "Choose your program." });
    }

    if (!yearSelect.value || !optionExists(yearSelect, yearSelect.value)) {
      errors.push({ field: yearSelect, message: "Choose your year of study." });
    }

    return {
      errors: errors,
      values: {
        name: name,
        email: email,
        studentId: studentId,
        program: programSelect.value,
        year: yearSelect.value,
        pronouns: pronounsInput.value.trim(),
        interests: interestsInput.value.trim(),
        emailUpdates: emailUpdates.checked,
        waitlistAlerts: waitlistAlerts.checked
      }
    };
  }

  function handleSubmit(event) {
    event.preventDefault();

    const result = validateProfile();
    if (result.errors.length > 0) {
      showErrors(result.errors);
      return;
    }

    profile = Object.assign({}, profile, result.values);
    window.App.saveProfile(profile);
    updateDisplay();
    clearAllErrors();
    window.App.showToast("Profile updated successfully.");

    if (status) {
      status.textContent = "";
      window.requestAnimationFrame(function () {
        status.textContent = "Profile updated successfully.";
      });
    }
  }

  function renderTable() {
    window.App.renderRegistrationTable(tableBody);
  }

  updateDisplay();
  fillForm();
  renderTable();
  window.App.updateStats();

  form.addEventListener("submit", handleSubmit);

  fields.forEach(function (field) {
    if (!field) {
      return;
    }
    const eventName = field.tagName === "SELECT" ? "change" : "input";
    field.addEventListener(eventName, function () {
      clearFieldError(field);
      if (errorSummary && !form.querySelector('[aria-invalid="true"]')) {
        errorSummary.hidden = true;
      }
    });
  });

  document.addEventListener("registrations:changed", function () {
    renderTable();
    window.App.updateStats();
  });
})();

