const { JSDOM, VirtualConsole } = require("jsdom");

const BASE = "http://localhost:8123/";
const errors = [];

function makeDom(path) {
  const virtualConsole = new VirtualConsole();
  virtualConsole.on("jsdomError", (err) => errors.push(`${path} jsdom: ${err.message}`));
  virtualConsole.on("error", (...args) => errors.push(`${path} console.error: ${args.join(" ")}`));
  return JSDOM.fromURL(BASE + path, {
    resources: "usable",
    runScripts: "dangerously",
    pretendToBeVisual: true,
    virtualConsole,
    beforeParse(window) {
      window.matchMedia = window.matchMedia || function () {
        return { matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} };
      };
      window.Element.prototype.scrollIntoView = function () {};
      if (window.HTMLDialogElement) {
        window.HTMLDialogElement.prototype.showModal = function () { this.setAttribute("open", ""); };
        window.HTMLDialogElement.prototype.close = function () {
          this.removeAttribute("open");
          this.dispatchEvent(new window.Event("close"));
        };
      }
    }
  });
}

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function load(path) {
  const dom = await makeDom(path);
  await new Promise((resolve) => {
    if (dom.window.document.readyState === "complete") resolve();
    else dom.window.addEventListener("load", resolve);
  });
  await wait(120);
  return dom;
}

function assert(condition, message) {
  if (!condition) throw new Error(message);
  console.log("PASS:", message);
}

(async () => {
  // Home
  let dom = await load("index.html");
  let doc = dom.window.document;
  assert(doc.querySelectorAll(".primary-nav a").length === 4, "home nav has 4 page links");
  assert(doc.querySelector("h1").textContent.includes("favorite"), "home h1 renders");
  assert(doc.querySelectorAll("#featuredCourses .course-card").length === 4, "home renders 4 featured course cards");
  assert(doc.querySelectorAll("#featuredCourses .status-pill--success").length >= 1, "home shows registered state");
  dom.window.close();

  // Catalog
  dom = await load("catalog.html");
  doc = dom.window.document;
  assert(doc.querySelectorAll("#courseGrid .course-card").length === 18, "catalog renders 18 course cards");
  assert(doc.getElementById("resultsCount").textContent.includes("18"), "catalog results count shows 18");
  const search = doc.getElementById("catalogSearch");
