input.content:
const { chromium } = require("playwright");
const axeSource = require("axe-core").source;

const BASE = "http://localhost:8123/";
const issues = [];

async function checkPage(browser, path, viewport) {
  const context = await browser.newContext({ viewport });
  const page = await context.newPage();
  const consoleErrors = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => consoleErrors.push("pageerror: " + err.message));
  await page.goto(BASE + path, { waitUntil: "networkidle" });
  await page.waitForTimeout(200);

  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  if (overflow > 1) issues.push(`${path} has horizontal overflow of ${overflow}px at ${viewport.width}px`);

  await page.addScriptTag({ content: axeSource });
  const results = await page.evaluate(async () => {
    return await axe.run(document, {
      runOnly: { type: "tag", values: ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "best-practice"] }
    });
  });

  const serious = results.violations.filter((v) => v.impact === "serious" || v.impact === "critical");
  serious.forEach((violation) => {
    issues.push(`${path} axe ${violation.impact}: ${violation.id} — ${violation.help} (${violation.nodes.length} nodes)`);
    violation.nodes.slice(0, 3).forEach((node) => {
      issues.push("   target: " + node.target.join(" ") + " — " + node.failureSummary);
    });
  });

  if (consoleErrors.length) {
    consoleErrors.forEach((error) => issues.push(`${path} console error: ${error}`));
  }

  console.log(`${path} @${viewport.width}: ${results.violations.length} violations (${serious.length} serious/critical), overflow ${overflow}px`);
  return { page, context, results };
}

(async () => {
  const browser = await chromium.launch({ args: ["--no-sandbox"] });
  const desktop = { width: 1440, height: 1000 };
  const mobile = { width: 390, height: 844 };

  for (const path of ["index.html", "catalog.html", "registration.html", "profile.html"]) {
    const { page, context } = await checkPage(browser, path, desktop);
    await page.screenshot({ path: `/tmp/campusflow-test/${path.replace(".html", "")}-desktop.png`, fullPage: true });
    await context.close();
  }

  // Mobile navigation test
  const mobileContext = await browser.newContext({ viewport: mobile });
  const mobilePage = await mobileContext.newPage();
  const mobileErrors = [];
  mobilePage.on("pageerror", (err) => mobileErrors.push(err.message));
  await mobilePage.goto(BASE + "index.html", { waitUntil: "networkidle" });
  await mobilePage.click(".nav-toggle");
  const expanded = await mobilePage.getAttribute(".nav-toggle", "aria-expanded");
  const navVisible = await mobilePage.isVisible("#primaryNav");
  if (expanded !== "true" || !navVisible) issues.push("Mobile navigation did not open correctly");
  await mobilePage.click('#primaryNav a[data-nav="catalog"]');
  await mobilePage.waitForLoadState("networkidle");
  if (!mobilePage.url().includes("catalog.html")) issues.push("Mobile navigation did not navigate to catalog");
  await mobilePage.screenshot({ path: "/tmp/campusflow-test/catalog-mobile.png", fullPage: true });
  if (mobileErrors.length) mobileErrors.forEach((e) => issues.push("mobile page error: " + e));
  await mobileContext.close();

  // Registration flow with preselected course
  const flowContext = await browser.newContext({ viewport: desktop });
  const flow = await flowContext.newPage();
  const flowErrors = [];
  flow.on("pageerror", (err) => flowErrors.push(err.message));
  flow.on("console", (msg) => { if (msg.type() === "error") flowErrors.push(msg.text()); });
  await flow.goto(BASE + "catalog.html", { waitUntil: "networkidle" });
  await flow.fill("#catalogSearch", "web development");
  await flow.waitForTimeout(300);
  const cards = await flow.locator("#courseGrid .course-card").count();
  if (cards !== 1) issues.push(`Expected 1 web development card, got ${cards}`);
  await flow.click('#courseGrid .course-card a[href*="registration.html"]');
  await flow.waitForLoadState("networkidle");
  const selected = await flow.inputValue("#courseSelect");
  if (selected !== "cs315") issues.push(`Preselected course should be cs315, got ${selected}`);
  if (!(await flow.isVisible("#coursePreview"))) issues.push("Course preview not visible on registration page");
  await flow.fill("#fullName", "Alex Morgan");
  await flow.fill("#studentId", "U20261234");
  await flow.fill("#email", "alex.morgan@university.edu");
  await flow.check("#consent");
  await flow.click('#registrationForm button[type="submit"]');
  await flow.waitForTimeout(300);
  const dialogOpen = await flow.locator("#appModal").evaluate((el) => el.open);
  if (!dialogOpen) issues.push("Confirmation dialog did not open");
  await flow.screenshot({ path: "/tmp/campusflow-test/registration-modal.png", fullPage: false });
  const modalTitle = await flow.textContent("#appModalTitle");
  if (!modalTitle.includes("registered")) issues.push("Confirmation dialog title missing");
  await flow.click('[data-modal-primary]');
  await flow.waitForTimeout(300);
  const rowCount = await flow.locator("#registrationTableBody tr").count();
  if (rowCount !== 3) issues.push(`Expected 3 registered rows after submit, got ${rowCount}`);
  if (flowErrors.length) flowErrors.forEach((e) => issues.push("flow error: " + e));
  await flowContext.close();

  // Mobile overflow on all pages
  for (const path of ["catalog.html", "registration.html", "profile.html"]) {
    const { context } = await checkPage(browser, path, mobile);
    await context.close();
  }

  await browser.close();

  if (issues.length) {
    console.log("\nISSUES:");
    issues.forEach((issue) => console.log("- " + issue));
    process.exitCode = 1;
  } else {
    console.log("\nAll browser checks passed.");
  }
})().catch((error) => {
  console.error("BROWSER TEST FAILURE:", error);
  process.exitCode = 1;
});

