const {JSDOM, VirtualConsole}=require('jsdom');
const axe=require('axe-core');
const pages=['index.html','catalog.html','registration.html','profile.html'];
const BASE='http://localhost:8123/';
(async()=>{
for(const f of pages){
  const vc=new VirtualConsole();
  vc.on('jsdomError',e=>console.log(f,'jsdomError',e.message));
  const dom=await JSDOM.fromURL(BASE+f,{resources:'usable',runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(w){w.matchMedia=w.matchMedia||function(){return{matches:false,addListener(){},removeListener(){},addEventListener(){},removeEventListener(){}}};w.Element.prototype.scrollIntoView=function(){};}});
  await new Promise(r=>dom.window.addEventListener('load',r));
  await new Promise(r=>setTimeout(r,200));
